#!/bin/bash
# Normalize+strip every set31 board (one pcbnew process each, segfault-safe).
# Reuses prep_set2.py (generic: <src> <routed_dst> <stripped_dst>).
#   stripped, unrouted boards -> boards_unrouted_set31/
#   normalized routed reference + .kicad_pro -> boards_set31/
# Auto-generated by assemble_corpus.py. Sources are modern KiCad (v6+).
set -u
SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
STRESS="${STRESS_DIR:-$HOME/Documents/kicad_stress_test}"
SRC="$STRESS/sources/github_set31"
KPY="${KICAD_PYTHON:-/Applications/KiCad/KiCad.app/Contents/Frameworks/Python.framework/Versions/Current/bin/python3}"
PREP="$SELF/prep_set2.py"
mkdir -p "$STRESS/boards_unrouted_set31" "$STRESS/boards_set31"

# short-name | source-filename-fragment (unique within github_set31/)
MAP=(
  "cm5io|cm5io"
  "imx8mp_som_evb|imx8mp_som_evb"
  "pic_programmer|pic_programmer"
  "pico_vga|pico_vga"
  "rk3328_som_evb|rk3328_som_evb"
  "rp2040_minimal|rp2040_minimal"
  "scalenode_cm4|scalenode_cm4"
  "stmp157_som_evb|stmp157_som_evb"
)

for entry in "${MAP[@]}"; do
  IFS='|' read -r name frag <<< "$entry"
  srcfile=$(find "$SRC" -maxdepth 1 -name '*.kicad_pcb' -name "*${frag}*" | head -1)
  if [ -z "$srcfile" ]; then echo "MISS $name (frag '$frag')"; continue; fi
  echo "== $name <- $(basename "$srcfile")"
  "$KPY" "$PREP" "$srcfile" "$STRESS/boards_set31/$name.kicad_pcb" \
         "$STRESS/boards_unrouted_set31/$name.kicad_pcb" 2>/dev/null || echo "  FAIL $name"
  profile="${srcfile%.kicad_pcb}.kicad_pro"
  [ -f "$profile" ] && cp "$profile" "$STRESS/boards_set31/$name.kicad_pro"
done
echo "Done. stripped -> boards_unrouted_set31/ ; routed reference -> boards_set31/"
